function draw(){drawColors();const host=document.getElementById('frameModelDraftList');if(!host)return;host.innerHTML=drafts.map((d,i)=>'<article class="frameDraftCard"><div><b>'+esc(C.size({variant_specs:d.specs}))+'</b><strong>'+C.price(d.price,{money,esc})+'</strong>'+(d.conflict?'<small class="framePriceConflict">برای این سایز چند قیمت ثبت شده؛ قیمت مشترک را ویرایش کنید.</small>':'')+'</div><button type="button" data-frame-active-draft="'+i+'">'+(d.active?'غیرفعال کردن':'فعال کردن')+'</button><button type="button" data-frame-edit-draft="'+i+'">ویرایش قیمت</button><button type="button" data-frame-remove-draft="'+i+'">حذف</button></article>').join('');}
function capture(){const form=document.getElementById('saleItemForm'),body=Object.fromEntries(new FormData(form));if(!colors.length)return 'ابتدا رنگ‌های مدل را انتخاب کنید.';body.variantColor=colors[0];const error=pbFramePrepareBody(body);if(error)return error;const raw=String(body.salePrice||'').trim(),price=Number(moneyRaw(raw));if(!raw||!Number.isSafeInteger(price)||price<0)return 'قیمت صحیح و غیرمنفی وارد کنید.';const specs={material:body.variantMaterial,widthCm:Number(body.variantWidthCm)||null,heightCm:Number(body.variantHeightCm)||null,diameterCm:Number(body.variantDiameterCm)||null,thicknessMm:Number(body.variantThicknessMm)||null};if(drafts.some((d,i)=>i!==editing&&sizeKey(d.specs)===sizeKey(specs)))return 'این سایز قبلاً قیمت‌گذاری شده؛ همان قیمت را ویرایش کنید.';const old=editing>=0?drafts[editing]:null,draft={id:old?.id,rowIds:old?.rowIds||{},active:old?.active!==false,conflict:false,specs,price,gallery:old?.gallery||[]};if(editing>=0)drafts[editing]=draft;else drafts.push(draft);editing=-1;form.elements.salePrice.value='';document.getElementById('frameAddVariant').textContent='＋ افزودن سایز و قیمت';draw();return '';}
