async function deleteModel(button){const g=C.groups(data.saleItems).find(x=>String(x.id)===button.dataset.frameDeleteModel);if(!g||button.disabled)return;if(!await pb920Confirm('مدل «'+g.model+'» و همهٔ گزینه‌های آن از فروش حذف شوند؟ سفارش‌های قبلی حفظ می‌شوند.'))return;const card=button.closest('[data-frame-model]');card.querySelectorAll('button,select').forEach(x=>x.disabled=true);try{await api('/api/rental/frame-models/'+g.id,{method:'DELETE',body:JSON.stringify({version:C.version(g.rows)})});cardSelections.delete(g.id);if(baseId===g.id)cancelSaleItemEdit();await pb854RefreshOverview('sales');renderModels();}catch(error){const msg=card.querySelector('[data-frame-card-message]');msg.textContent=error.error==='frame_model_changed'?'مدل تغییر کرده؛ صفحه را تازه و دوباره حذف کنید.':'حذف مدل انجام نشد؛ دوباره تلاش کنید.';card.querySelectorAll('button,select').forEach(x=>x.disabled=false);}}
