const style=document.createElement('style');style.textContent=C.cardStyles()+`
#frameModelTopRow{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;align-items:start;margin:12px 0}#frameModelTopRow>.field{display:grid!important;grid-template-rows:20px auto;gap:6px!important;align-content:start;line-height:20px;min-width:0;width:auto!important;grid-column:auto!important}#frameModelTopRow label{font-size:13px;line-height:20px;margin:0;white-space:nowrap}#frameModelTopRow [data-frame-option=thicknesses]~label{font-size:13px}
.frameNativeSelect,.frameKindNative{position:absolute!important;width:1px!important;height:1px!important;opacity:0;pointer-events:none}.frameSelectMenu{position:relative;min-width:0}.frameSelectMenu summary{list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:6px;border:1px solid #dbe5f2;border-radius:9px;background:#fff;padding:10px;min-height:42px;font-size:13px}.frameSelectMenu summary::-webkit-details-marker{display:none}.frameSelectMenu summary span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.frameSelectPanel{position:absolute;z-index:80;top:calc(100% + 4px);right:0;min-width:100%;width:240px;max-width:calc(100vw - 60px);padding:8px;border:1px solid #dbe5f2;border-radius:10px;background:#fff;box-shadow:0 8px 24px #10182820}.frameSelectOptions{display:grid;max-height:190px;overflow:auto}.frameSelectPanel button{font:inherit;border:0;background:#fff;border-radius:6px;text-align:right;padding:9px;cursor:pointer;width:100%}.frameSelectOptions button[aria-pressed=true]{background:#eef3ff;color:#315efb}.frameSelectPanel .frameOptionAdd{border-top:1px solid #dbe5f2;color:#315efb;margin-top:6px}.frameSelectPanel input{width:100%;font:inherit}.frameSelectPanel .frameOptionEditor[hidden],.frameKindEditor[hidden]{display:none!important}
#frameModelColorSection,#frameModelPhotoSection,#frameVariantComposer{border-top:1px solid #dbe5f2;padding-top:12px;margin-top:16px}#frameVariantFields h3{font-size:15px}.frameChooseColor{position:relative;display:inline-flex;border:1px solid #dbe5f2;border-radius:9px;background:#fff;color:#315efb;padding:10px;cursor:pointer}.frameChooseColor input[type=color]{position:absolute;inset:0;width:100%!important;height:100%!important;opacity:0;cursor:pointer}#frameModelColorList,#framePhotoColorList{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:12px 0}.frameModelColorChip{display:inline-flex;align-items:center;gap:5px}.frameVariantSwatch{display:inline-block;width:24px;height:24px;border-radius:50%;border:1px solid #cbd5e1;background:var(--frame-color)}.frameModelColorChip button{border:0;background:transparent;font-size:20px;cursor:pointer;color:#667085;padding:2px}#framePhotoCaption{font-size:12px;color:#667085}.framePhotoUpload{display:inline-block;position:relative;cursor:pointer;background:#eef3ff;color:#315efb;padding:10px;border-radius:9px}.framePhotoUpload input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}#frameColorGallery{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}#frameColorGallery figure{position:relative;margin:0;width:100px;height:100px}#frameColorGallery img{display:block!important;width:100%;height:100%;object-fit:contain;border:1px solid #dbe5f2;border-radius:10px}#frameColorGallery button{position:absolute;top:3px;left:3px;border:1px solid #dbe5f2;border-radius:50%;background:#fff;width:24px;height:24px;cursor:pointer}.frameVariantComposerGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.frameVariantComposerGrid>.field{width:100%!important;grid-column:auto!important;min-width:0}.frameDraftCard{display:flex;align-items:center;gap:10px;border:1px solid #dbe5f2;border-radius:10px;padding:10px;margin:8px 0}.frameDraftCard>div{flex:1}.frameDraftCard strong{display:block;margin-top:5px}.frameDraftCard button{font:inherit;border:1px solid #dbe5f2;border-radius:8px;background:#fff;padding:7px}.framePriceConflict,#frameVariantDraftMessage,#framePhotoMessage,#frameModelColorMessage{color:#b42318}@media(max-width:600px){#frameModelTopRow{gap:5px}#frameModelTopRow label{font-size:11px}.frameSelectMenu summary{padding:7px 4px;font-size:11px}.frameSelectPanel{position:fixed;top:auto;bottom:76px;right:20px;left:20px;width:auto;max-width:none;max-height:calc(100vh - 150px);overflow:auto}.frameVariantComposerGrid{grid-template-columns:1fr}.frameDraftCard{flex-wrap:wrap}}
`;document.head.append(style);
